// Native Chaos chapter: two core questions.
const markup="<div class=\"page-shell dao-reading chaos-reading\" data-chaos-page>\n<nav class=\"breadcrumbs\" aria-label=\"当前位置\"><a href=\"#/tian\">天道</a><span aria-hidden=\"true\">/</span><a href=\"#/map?focus=origin\">本源</a><span aria-hidden=\"true\">/</span><span aria-current=\"page\">一：混沌</span></nav>\n<header class=\"page-heading\"><span class=\"eyebrow\">TIAN / 本源 / 1.2</span><h1>一：混沌</h1><p class=\"chaos-definition\">无有之地，<br>万物得以生成的潜能。</p><p class=\"page-intro\">什么是混沌？源头为什么要先创造混沌？从无形的整体，认识使万物创造成为可能的潜能场。</p></header>\n<figure class=\"opening-illustration\"><img src=\"/assets/chaos/混沌未分.jpg\" width=\"2048\" height=\"683\" alt=\"淡墨在米色纸上流动，边缘渐显山水轮廓，中央仍为未分的雾气\" fetchpriority=\"high\"><figcaption>由未分，到成形 · 一幅关于潜能的意象</figcaption></figure>\n<div class=\"article-layout\"><aside class=\"article-toc\"><span class=\"eyebrow\">本页内容</span><button type=\"button\" data-scroll=\"chaos-what\">01 什么是混沌？</button><button type=\"button\" data-scroll=\"chaos-why\">02 源头为什么要先创造混沌？</button></aside><article class=\"prose chaos-body\"><section class=\"section\" id=\"chaos-what\" aria-labelledby=\"chaos-what-title\">\n<div class=\"section-title\"><span class=\"num\">01</span><h2 id=\"chaos-what-title\">什么是混沌？</h2></div>\n<p class=\"lede\">无有之地：具体的万物尚未显现，形成万物的可能已经蕴含其中。</p>\n<p>当我们把目光从山川、星辰与生命，移向它们尚未取得具体形态之时，会遇到一个难以用日常经验描述的问题：如果还没有一件可以被指出、被命名的事物，存在究竟是什么样子？</p>\n<p>《三道哲学》把这种<strong>尚未分化、尚未形成具体万物，却具有生成能力的原初整体</strong>称为混沌。“一”强调它的整体性；“混沌”描述具体区别尚未展开的状态。山还没有山的轮廓，水还没有水的流向，万物的可能尚未成为各自确定的存在。</p>\n<blockquote class=\"quote\">无容纳着有，<br>非空间容纳着空间，<br>整体容纳着部分。<cite>《与神对话》第一卷 · 本文译述</cite><span class=\"original\" lang=\"en\">It is the nothing which holds the everything.<br>It is the non-space which holds the space.<br>It is the all which holds the parts.</span></blockquote>\n<p>这三句话给了我们一个入口。在《与神对话》的叙述中，最初只有“一切万有”，整体之外没有另一个存在。书中借 Nothing、Non-space 与 All，描述整体与具体事物的关系。我们借此理解混沌：当部分尚未被区分出来时，整体已经在；当具体形态尚未显现时，生成的可能并未缺席。</p>\n<h3>这里什么都有，又什么都没有</h3>\n<p>“什么都没有”，说的是还没有任何已经成形的具体万物；“什么都有”，说的是形成万物的潜能。两句话分别从形态与能力来理解同一整体。把这两个层次放在一起，才能明白“无有之地”的含义。</p>\n<p>Nothing 可以借 No-Thing 来体会：尚不能把整体指认为某一个特定的东西。我们习惯靠形状、边界、位置来辨认事物，因而容易把“找不到某个具体对象”理解成“绝对不存在”。混沌要求我们把目光再向前推一步，看见具体对象得以出现的可能。</p>\n<p>“非空间容纳着空间”，又把这个问题推向空间本身。设想一间空房子，里面虽然没有家具，房间的边界、尺寸与位置却已经确定。这里追问的更深：当“这里”与“那里”尚未被分开时，使这些区分得以成立的整体，应当怎样理解？所谓“容纳”，表达的是根本与显现的关系，不能只按一个大盒子装着小盒子的方式想象。</p>\n<p>“整体容纳着部分”，则改变了我们理解“一”的顺序。日常经验常从一块石头、一棵树、一颗星开始，再把它们合称为世界。在本章的生成图景中，整体先于部分的区分：万物从整体之中取得各自的形式，每一部分仍然属于同一整体。</p>\n<figure class=\"figure whole-figure\" aria-labelledby=\"chaos-whole-heading\"><div class=\"eyebrow\">同一个整体 · 三种理解</div><h3 id=\"chaos-whole-heading\">“无”与“有”，怎样同时成立？</h3>\n<div class=\"whole-stage\" data-lens-state=\"formless\"><svg viewBox=\"0 0 600 250\" role=\"img\" aria-label=\"始终保留的完整圆形，以不同线条提示无形、整体与潜能\"><defs><radialGradient id=\"chaos-whole-mist\"><stop stop-color=\"#94a48b\" stop-opacity=\".6\"/><stop offset=\"1\" stop-color=\"#94a48b\" stop-opacity=\".03\"/></radialGradient></defs><ellipse cx=\"300\" cy=\"125\" rx=\"198\" ry=\"106\" fill=\"url(#chaos-whole-mist)\"/><ellipse cx=\"300\" cy=\"125\" rx=\"198\" ry=\"106\" fill=\"none\" stroke=\"#3f5141\" stroke-opacity=\".45\"/><g class=\"lens-pattern\" data-lens-art=\"formless\" fill=\"none\" stroke=\"#3f5141\" stroke-opacity=\".35\"><path d=\"M120 112Q210 60 300 113T480 112M113 136Q210 86 300 136T487 136M132 159Q222 115 312 159T467 159\"/></g><g class=\"lens-pattern\" data-lens-art=\"whole\" opacity=\".12\" fill=\"none\" stroke=\"#92713f\"><ellipse cx=\"300\" cy=\"125\" rx=\"160\" ry=\"84\"/><ellipse cx=\"300\" cy=\"125\" rx=\"118\" ry=\"61\"/><ellipse cx=\"300\" cy=\"125\" rx=\"75\" ry=\"39\"/></g><g class=\"lens-pattern\" data-lens-art=\"potential\" opacity=\".12\" fill=\"none\" stroke=\"#92713f\" stroke-dasharray=\"4 6\"><path d=\"M300 125Q210 80 174 90M300 125Q360 60 420 75M300 125Q390 160 433 169M300 125Q245 175 198 181\"/><circle cx=\"174\" cy=\"90\" r=\"10\"/><circle cx=\"420\" cy=\"75\" r=\"10\"/><circle cx=\"433\" cy=\"169\" r=\"10\"/><circle cx=\"198\" cy=\"181\" r=\"10\"/></g><text x=\"300\" y=\"130\" text-anchor=\"middle\" class=\"svg-major\">一</text></svg></div>\n<div class=\"choices\" aria-label=\"选择混沌的理解角度\"><button class=\"choice\" type=\"button\" data-lens=\"formless\" aria-pressed=\"true\">无形</button><button class=\"choice\" type=\"button\" data-lens=\"whole\" aria-pressed=\"false\">整体</button><button class=\"choice\" type=\"button\" data-lens=\"potential\" aria-pressed=\"false\">潜能</button></div><p class=\"readout\" id=\"chaos-lens-note\" aria-live=\"polite\"><strong>无形：</strong>尚无可逐一辨认的具体万物；生成的可能仍然在。</p><figcaption class=\"caption\">圆形表示完整性，虚线提示尚未实现的可能。三个角度共同描述混沌，图形不是它的实际外观。</figcaption></figure>\n<h3>由古至今，人类怎样接近这个问题？</h3>\n<p>对无形与生成的追问，有着漫长的历史。神话把它写成世界开端的景象，哲学尝试说明它的存在方式，现代物理则在具体理论中研究状态、可能性与可见的激发。这些探索帮助我们从不同方向接近混沌：无形何以有，未成何以生，整体何以容纳万物。</p>\n<p>古希腊赫西俄德的《神谱》把 <em>Chaos</em> 放在生成叙事的开端。这个词在其早期语境中指向张开的空隙，而非日常所谓杂乱。随后，天地与神祇的谱系逐渐展开，其中幽暗与黑夜由 Chaos 生出。古人以神话追问：在我们熟悉的世界秩序出现之前，是什么？Chaos 给这个追问留下了一幅原初空场的意象。</p>\n<p>《道德经》用“有物混成，先天地生”描写道，又说：“道冲，而用之或不盈。渊兮，似万物之宗。”混成使人想到尚未分开的整体，渊使人想到深广而难以穷尽的根源。原文谈的是道；沿着本章对“道生一”的理解，我们也借这些意象体会潜能尚未展开时的状态。</p>\n<p>一道浪显出了形状，海仍有这道浪未曾显出的深广。即使水面暂时没有清晰的浪峰，也不能据此说海的存在与成浪的可能一同消失。这个意象帮助我们把当前的显现与它所依托的整体同时放在眼前。</p>\n<figure class=\"figure\" style=\"margin-top:0\"><svg viewBox=\"0 0 460 300\" role=\"img\" aria-labelledby=\"chaos-sea-title chaos-sea-desc\"><title id=\"chaos-sea-title\">海与浪的意象</title><desc id=\"chaos-sea-desc\">表层波浪之下，淡色水纹向深处延展。切换可查看浪形或深广背景。</desc><defs><linearGradient id=\"chaos-sea-grad\" x2=\"0\" y2=\"1\"><stop stop-color=\"#c4d1c0\" stop-opacity=\".55\"/><stop offset=\"1\" stop-color=\"#577768\" stop-opacity=\".18\"/></linearGradient></defs><g id=\"chaos-sea-detail\"><path d=\"M8 105Q55 55 105 105T202 105 300 105 398 105T452 105V282H8Z\" fill=\"url(#chaos-sea-grad)\"/><path d=\"M15 155Q70 120 125 155T235 155 345 155 450 155M15 207Q70 175 125 207T235 207 345 207 450 207M15 258Q70 233 125 258T235 258 345 258 450 258\" stroke=\"#6d8976\" opacity=\".25\" fill=\"none\"/></g><path d=\"M8 105Q55 55 105 105T202 105 300 105 398 105T452 105\" id=\"chaos-sea-wave\" fill=\"none\" stroke=\"#315d50\" stroke-width=\"2\"/><text class=\"svg-label\" x=\"230\" y=\"44\" text-anchor=\"middle\">可见的形态</text><text class=\"svg-label\" x=\"230\" y=\"245\" text-anchor=\"middle\" id=\"chaos-sea-depth-label\">尚未尽显的深广</text></svg><div class=\"choices\" aria-label=\"选择海与浪的视角\"><button class=\"choice\" type=\"button\" data-sea=\"wave\" aria-pressed=\"false\">看浪形</button><button class=\"choice\" type=\"button\" data-sea=\"whole\" aria-pressed=\"true\">看海与浪</button></div><figcaption class=\"caption\" id=\"chaos-sea-note\" aria-live=\"polite\">这一道浪显出形状，海仍有超出这一形状的深广。</figcaption></figure>\n<p>宋代张载在《正蒙·太和》中说：“太虚无形，气之本体，其聚其散，变化之客形尔。”在他的思想中，太虚与气、无形与有形，通过聚散变化相联系。无形具有自己的存在方式，有形则是变化中的具体呈现。借“太虚”理解混沌，最有力量之处，正是它使无形与生成保持联系。</p>\n<h3>Hyle 与 Potentia：尚未成形，怎样仍然具有能力？</h3>\n<p>赫尔墨斯传统中的 <em>Hyle</em>，通常译作“质料”，把问题引向形式的承载与生成。《论质料》残篇把质料称为“生成之器”，并把无形、接受生成、进入活动与取得形式联系起来。尚未取得某个确定的样子，同时具有受形的能力，这是质料一词对于本章的关键启发。</p>\n<p>亚里士多德通过潜能与现实，说明一件事物能够成为什么，以及它已经成为什么。可以成为一张桌子的木材，还没有取得桌子的形式；但成为桌子的能力也不能因为桌子尚未出现而被抹去。<em>Potentia</em> 使我们能够谈论这种“尚未实现、却有可能实现”的存在方式。</p>\n<p>海森堡在《物理学与哲学》中重新借用这一思想。他在讨论物质结构时，把亚里士多德的质料与潜能同能量作哲学比较，并借“形式”讨论基本粒子的现实化。它让古老的追问继续进入现代思想：面对已经发生的事件，我们是否也需要理解事件发生以前的可能性？这条线索照亮的是潜能与现实的联系。</p>\n<h3>量子真空与电子场基态：没有粒子激发，结构仍在</h3>\n<p>现代物理给出了一个可以更精确讨论的对照。在通常平直时空的自由量子场描述中，真空是没有粒子激发的最低能量状态。此时，场理论规定的结构、允许的激发及相应规律仍然成立。真空也具有量子相关，不能被理解为完全没有物理性质。</p>\n<p>以自由电子场为例，基态没有电子或正电子激发；电子与正电子可以作为同一场的不同激发来描述。这里值得反复体会的是：<strong>某种具体激发尚未出现，与使这种激发成为可能的结构不存在，具有不同含义。</strong>这让“尚未显现而具有生成可能”变得更容易理解。</p>\n<figure class=\"figure field-comparison\" id=\"chaos-field-comparison\" aria-labelledby=\"chaos-vacuum-title\">\n<div class=\"eyebrow\">混沌 · Hyle · 渊 / 基态与潜能</div><h3 id=\"chaos-vacuum-title\">尚无具体激发，结构仍在</h3>\n<div class=\"field-layout\">\n<div class=\"field-visual\">\n<div class=\"field-scene\" id=\"chaos-field-scene\" data-field-state=\"ground\" role=\"img\" aria-label=\"基态：层叠细线表示始终存在的理论结构，没有电子或正电子激发\">\n<svg class=\"field-pattern\" viewBox=\"0 0 640 320\" preserveAspectRatio=\"none\" aria-hidden=\"true\"><defs><radialGradient id=\"chaos-field-haze\"><stop stop-color=\"#9aa98e\" stop-opacity=\".32\"/><stop offset=\"1\" stop-color=\"#9aa98e\" stop-opacity=\"0\"/></radialGradient></defs><ellipse cx=\"324\" cy=\"164\" rx=\"300\" ry=\"158\" fill=\"url(#chaos-field-haze)\"/><g class=\"field-modes\"><path d=\"M-30 34C75 0 132 65 236 36S414 2 512 38 642 54 680 28\"/><path d=\"M-30 57C75 23 132 88 236 59S414 25 512 61 642 77 680 51\"/><path d=\"M-30 80C75 46 132 111 236 82S414 48 512 84 642 100 680 74\"/><path d=\"M-30 103C75 69 132 134 236 105S414 71 512 107 642 123 680 97\"/><path d=\"M-30 126C75 92 132 157 236 128S414 94 512 130 642 146 680 120\"/><path d=\"M-30 149C75 115 132 180 236 151S414 117 512 153 642 169 680 143\"/><path d=\"M-30 172C75 138 132 203 236 174S414 140 512 176 642 192 680 166\"/><path d=\"M-30 195C75 161 132 226 236 197S414 163 512 199 642 215 680 189\"/><path d=\"M-30 218C75 184 132 249 236 220S414 186 512 222 642 238 680 212\"/><path d=\"M-30 241C75 207 132 272 236 243S414 209 512 245 642 261 680 235\"/><path d=\"M-30 264C75 230 132 295 236 266S414 232 512 268 642 284 680 258\"/><path d=\"M-30 287C75 253 132 318 236 289S414 255 512 291 642 307 680 281\"/></g><g class=\"field-cross-modes\"><path d=\"M35 -20C73 81 1 184 43 340\"/><path d=\"M107 -20C145 81 73 184 115 340\"/><path d=\"M179 -20C217 81 145 184 187 340\"/><path d=\"M251 -20C289 81 217 184 259 340\"/><path d=\"M323 -20C361 81 289 184 331 340\"/><path d=\"M395 -20C433 81 361 184 403 340\"/><path d=\"M467 -20C505 81 433 184 475 340\"/><path d=\"M539 -20C577 81 505 184 547 340\"/><path d=\"M611 -20C649 81 577 184 619 340\"/></g><g class=\"field-contours\"><ellipse cx=\"320\" cy=\"161\" rx=\"113\" ry=\"65\"/><ellipse cx=\"320\" cy=\"161\" rx=\"179\" ry=\"100\"/><ellipse cx=\"320\" cy=\"161\" rx=\"246\" ry=\"135\"/></g></svg>\n<p class=\"field-scene-label\">同一自由电子场 · 结构纹理</p>\n<div class=\"field-particles\" aria-hidden=\"true\"><span class=\"quantum\" id=\"chaos-electron\">e⁻</span><span class=\"quantum positron\" id=\"chaos-positron\">e⁺</span></div>\n<p class=\"field-scene-bottom\">背景始终保留</p>\n</div>\n<p class=\"vacuum-status\" id=\"chaos-vacuum-status\">基态：无电子与正电子激发</p>\n<div class=\"choices\" aria-label=\"选择自由电子场的示意状态\"><button class=\"choice\" type=\"button\" data-vacuum=\"ground\" aria-pressed=\"true\">基态</button><button class=\"choice\" type=\"button\" data-vacuum=\"electron\" aria-pressed=\"false\">电子激发态</button><button class=\"choice\" type=\"button\" data-vacuum=\"pair\" aria-pressed=\"false\">电子与正电子激发态</button></div>\n<p id=\"chaos-vacuum-note\" class=\"readout\" aria-live=\"polite\"><strong>基态：</strong>没有电子或正电子激发，允许怎样的激发仍由场的理论结构规定。</p>\n</div>\n<aside class=\"field-reading\" aria-labelledby=\"chaos-field-reading-title\" aria-live=\"polite\"><p class=\"field-reading-label\" id=\"chaos-field-reading-title\">由基态，理解未显的可能</p><p class=\"field-core\">尚无具体激发，<br>生成的可能与结构仍在。</p><dl class=\"field-parallels\"><div><dt>混沌</dt><dd id=\"chaos-field-chaos\">具体区别尚未展开，形成万物的能力仍在。</dd></div><div><dt>Hyle</dt><dd id=\"chaos-field-hyle\">尚未成形而能够受形，潜能可以进入生成。</dd></div><div><dt>渊</dt><dd id=\"chaos-field-abyss\">显现尚未展开，深广的可能并未被用尽。</dd></div></dl></aside>\n</div>\n<figcaption class=\"caption\">细线表示有结构的背景，圆点表示所选激发，均为概念记号。这是一种哲学对照：混沌、Hyle、“渊”与自由电子场各有自身含义。按钮比较不同状态，不模拟粒子产生过程。</figcaption>\n</figure>\n<p>狄拉克海提供过另一幅历史图景：负能量电子态被设想为填满，其中留下的空穴与正电子相联系。它同样使人注意到，可见现象可能依托更深的结构。现代量子场论对粒子与反粒子有了更一般的描述，我们可以保留这幅历史图景带来的启发，同时沿现代场论理解电子场基态。</p>\n<details class=\"action-fold dao-fold\"><summary>狄拉克海与现代电子场，分别怎样描绘背景？</summary><div class=\"inside action-prose\"><div class=\"model-card\" aria-label=\"历史狄拉克海与现代自由电子场的比较\"><div><h4>历史图景 · 狄拉克海</h4><div class=\"levels\" aria-hidden=\"true\"><div class=\"level\"><span>正能</span><span class=\"level-line\"></span></div><div class=\"level zero\"><span>分界</span><span class=\"level-line\"></span></div><div class=\"level\"><span>负能</span><span class=\"level-line\">●　●　●　●</span></div><div class=\"level\"><span>负能</span><span class=\"level-line\">●　●　<span id=\"chaos-dirac-hole\">●</span>　●</span></div><div class=\"level\"><span>负能</span><span class=\"level-line\">●　●　●　●</span></div></div><div class=\"choices\" aria-label=\"查看历史狄拉克海中的空穴\"><button class=\"choice\" type=\"button\" data-dirac=\"filled\" aria-pressed=\"true\">负能态填满</button><button class=\"choice\" type=\"button\" data-dirac=\"hole\" aria-pressed=\"false\">留下一个空穴</button></div><p class=\"model-caption\" id=\"chaos-dirac-note\" aria-live=\"polite\">在历史海图景中，负能态被设想为电子填满。</p></div><div><h4>现代描述 · 自由电子场</h4><div class=\"concept-flow\" style=\"grid-template-columns:1fr 20px 1fr;margin-top:22px\"><div class=\"node\">基态<small>无 e⁻、e⁺ 激发</small></div><span class=\"arrow\" aria-hidden=\"true\">→</span><div class=\"node\">激发态<small>电子／正电子</small></div></div><p class=\"model-caption\">分别定义电子、正电子的产生与湮灭算符，真空由两类湮灭算符共同定义。</p><p class=\"model-caption\"><strong>回到混沌 · Hyle · 渊：</strong>借基态与激发的对照，理解尚未显现与具体成形的关系；背景并未被一次显现用尽。</p></div></div></div></details>\n<p class=\"note\">本章把这些思想放在一起，是《三道哲学》围绕“无形、整体与潜能”作出的哲学对读。各传统保留自己的含义；量子真空与场的基态是受具体理论和物理条件约束的状态，并不直接证明它们就是混沌。</p>\n<p>现在，混沌可以获得一个完整的理解：<strong>无形，说明具体万物尚未出现；整体，说明部分尚未分化；潜能，说明万物仍然能够生成。</strong>从神话中的开端、哲学中的质料与太虚，到物理学中的基态与激发，人类不断以新的语言，追问可见世界背后的可能。</p>\n</section>\n<section class=\"section\" id=\"chaos-why\" aria-labelledby=\"chaos-why-title\">\n<div class=\"section-title\"><span class=\"num\">02</span><h2 id=\"chaos-why-title\">源头为什么要先创造混沌？</h2></div>\n<p class=\"lede\">为了使一切创造成为可能：源头展开自身的潜能，让万物能够取得形式。</p>\n<p>上一章提出，源头的根本欲望是“认识我是谁”。现在，我们沿着创造的展开继续追问：源头具有创造性，为什么还要先有混沌？混沌在万物的生成中，究竟承担什么作用？</p>\n<p>《三道哲学》的回答是：<strong>混沌是源头为万物的生成所展开的原初潜能场（Potential Field）。</strong>这个名称把混沌在创造中的作用说了出来：它容纳尚未实现的可能，使不同形式的生成具有基础。</p>\n<div class=\"potential-definition\"><span class=\"eyebrow\">POTENTIAL FIELD</span><p>潜能场</p><div>源头的创造性，展开为万物得以生成的可能。</div><small>《三道哲学》对混沌的哲学描述</small></div>\n<h3>从“能够创造”，到“具体的万物能够形成”</h3>\n<p>创造的能力与已经完成的创造，之间有一段值得追问的关系。一位雕塑家具有创造能力，但这句话还没有告诉我们：什么可以接受形式，什么样的活动使形式出现，以及为什么最终出现的是这一件作品。要理解一件作品的生成，就需要把能力、受形的可能与具体实现联系起来。</p>\n<p>同样，当我们说“源头能够创造万物”，我们已经说明创造从何而来，却还需要说明万物何以能够形成。混沌正处在这两个问题之间。它让源头的创造性具有可以展开为不同形式的可能，使“能够创造”与“具体生成”之间的关系变得可以理解。</p>\n<p>雕塑家可以从外界取得材料，而在本章的本源观中，源头之外没有另一个存在。因而，万物生成的基础也来自源头自身。<strong>源头展开自身的潜能，使尚未出现的形式成为可以实现的可能；这种潜能尚未分化的整体状态，就是“一”。</strong></p>\n<figure class=\"figure creation-figure\" aria-labelledby=\"chaos-creation-heading\"><div class=\"eyebrow\">道生一 · 创造何以可能</div><h3 id=\"chaos-creation-heading\">从根源，到潜能，再到形式</h3><div class=\"creation-map\" aria-label=\"创造的三个解释层次\"><button type=\"button\" class=\"creation-node\" data-creation=\"source\" aria-pressed=\"false\"><span>道 · 源头</span><small>觉知与创造性</small></button><span class=\"creation-arrow\" aria-hidden=\"true\">→</span><button type=\"button\" class=\"creation-node\" data-creation=\"potential\" aria-pressed=\"true\"><span>一 · 混沌</span><small>Potential Field · 潜能场</small></button><span class=\"creation-arrow\" aria-hidden=\"true\">→</span><button type=\"button\" class=\"creation-node\" data-creation=\"form\" aria-pressed=\"false\"><span>具体形式</span><small>可能取得实际呈现</small></button></div><p class=\"readout\" id=\"chaos-creation-note\" aria-live=\"polite\"><strong>本章的中心：</strong>源头展开自身的潜能，使不同形式的生成成为可能。</p><figcaption class=\"caption\">点击查看各层的作用。箭头表示解释关系；潜能怎样通过差异与相互作用取得形式，将在后续章节展开。</figcaption></figure>\n<p>从这个角度看，“先创造混沌”首先说明生成的层次：在讨论某种确定的事物怎样形成之前，先理解它为什么能够形成。“道生一”把创造的根源与生成的可能联系起来。它呈现的是本章选择的哲学解释，并非一张已经测定的宇宙时间表。</p>\n<h3>为什么 Hyle 又叫“质料”？</h3>\n<p>把混沌比作“创造万物的原材料”，能够帮助我们抓住这一层关系。泥可以成为碗、瓶或鸟；当它还没有取得这些形式时，成形的可能已经在。塑形活动使某一种可能获得确定的呈现，因此我们能同时谈论“作为材料的泥”和“作为成品的碗”。</p>\n<figure class=\"figure art-figure\" aria-labelledby=\"chaos-clay-title\"><div class=\"eyebrow\">日常类比 · 潜能与形式</div><h3 id=\"chaos-clay-title\">一团泥，可以成为什么？</h3><div class=\"clay-canvas\"><img src=\"/assets/chaos/潜能与成形.jpg\" width=\"1672\" height=\"941\" loading=\"lazy\" alt=\"同一质感的泥团与碗、瓶、鸟，三种已成形式作为泥的不同可能并置\"><svg viewBox=\"0 0 1672 941\" aria-hidden=\"true\" class=\"art-overlay\"><defs><mask id=\"chaos-clay-mask\"><rect width=\"1672\" height=\"941\" fill=\"white\"/><ellipse cx=\"847\" cy=\"653\" rx=\"424\" ry=\"252\" fill=\"black\"/><ellipse id=\"chaos-clay-hole\" cx=\"333\" cy=\"275\" rx=\"276\" ry=\"203\" fill=\"black\"/></mask></defs><rect id=\"chaos-clay-veil\" width=\"1672\" height=\"941\" fill=\"#efeee8\" opacity=\"0\" mask=\"url(#chaos-clay-mask)\"/><ellipse id=\"chaos-clay-ring\" cx=\"333\" cy=\"275\" rx=\"276\" ry=\"203\" fill=\"none\" stroke=\"#96784b\" stroke-width=\"3\" stroke-dasharray=\"8 9\" opacity=\"0\"/></svg></div><div class=\"choices\" aria-label=\"选择泥的不同成形可能\"><button class=\"choice\" type=\"button\" data-clay=\"all\" aria-pressed=\"true\">看潜能</button><button class=\"choice\" type=\"button\" data-clay=\"bowl\" aria-pressed=\"false\">成碗</button><button class=\"choice\" type=\"button\" data-clay=\"vase\" aria-pressed=\"false\">成瓶</button><button class=\"choice\" type=\"button\" data-clay=\"bird\" aria-pressed=\"false\">成鸟</button></div><p class=\"readout\" id=\"chaos-clay-note\" aria-live=\"polite\"><strong>多种可能：</strong>泥团尚未成为碗、瓶或鸟，却可以在相应的塑形活动中，取得其中一种形式。</p><figcaption class=\"caption\">三件物表示并列的成形可能。泥土已经是一种具体材料，这里借它说明材料与形式的关系；Hyle 的讨论尺度仍依前文理解。</figcaption></figure>\n<p>Hyle 的“质料”之义，着重说明这种能够受形、进入生成的基础。赫尔墨斯残篇所说的“生成之器”，也把重点放在承载与变化上：无形之中可以发生生成，生成使形式出现。它让“潜能”获得了一个具体的方向——能够取得形式，能够成为某种确定的存在。</p>\n<p>泥、木材与金属已经有各自的性质，混沌的讨论则继续追问这些具体材料得以形成的基础。所以，“原材料”是一个便于理解的比喻；在本章的哲学模型中，混沌作为原初潜能场，容纳的是万物生成的可能，具体物质本身也属于其后展开的形式。</p>\n<h3>“潜能场”中的“场”，应当怎样理解？</h3>\n<p>这里的“场”强调生成可能所依托的整体。我们谈论一个事物时，往往只注意它已经获得的轮廓，而把使它得以形成的基础留在了视野之外。“潜能场”使我们同时关注这两层：眼前的形式，以及形式能够出现的可能。</p>\n<p>它也帮助我们理解为什么混沌被称为“一”。如果万物的生成基础来自同一源头，那么不同事物取得形式时，彼此仍有共同的根本。混沌作为尚未分化的整体，使多样性能够从共同基础中展开。这里的“一”具有连续性：道、混沌与万物，是沿着根源、潜能与显现理解同一生成关系。</p>\n<p>“潜能场”是本体系为说明创造何以可能而采用的哲学概念。物理学中的电子场、量子态或势场有各自精确的定义；本章借其中的关系帮助理解潜能，并不把 Potential Field 当作已被物理学发现的某一种场。</p>\n<h3>潜能怎样容纳万物，又不预先成为万物？</h3>\n<p>仍以泥为例。它能够成碗，也能够成瓶，这两种可能可以同时被讨论。但一次具体塑形会使它取得确定的形状。能够成为的丰富性，与已经成为的确定性，正是潜能和现实之间的区别。</p>\n<p>当我们说“混沌之中什么都有”，说的是生成的可能尚未被某种形式限定。星辰、生命与山河，还没有以缩小的成品形式储存在其中。创造的意义就在于：可能要经过展开，才获得实际的形式；某一种形式的出现，也没有把整体的一切可能表达完毕。</p>\n<figure class=\"figure\" aria-labelledby=\"chaos-potential-figure-title\"><div class=\"eyebrow\">概念示意 · 点击三个位置</div><h3 id=\"chaos-potential-figure-title\">从“尚未成为”，理解“能够成为”</h3>\n<svg class=\"desktop-viz\" viewBox=\"0 0 780 280\" role=\"img\" aria-labelledby=\"chaos-potential-svg-title chaos-potential-svg-desc\"><title id=\"chaos-potential-svg-title\">潜能与形式的关系</title><desc id=\"chaos-potential-svg-desc\">三个位置分别呈现未取得形式、进入活动和具体形式。按钮用于逐步查看，图形不表示宇宙真实的创生外观。</desc><defs><radialGradient id=\"chaos-potential-mist\"><stop stop-color=\"#94a48b\" stop-opacity=\".7\"/><stop offset=\"1\" stop-color=\"#94a48b\" stop-opacity=\"0\"/></radialGradient></defs><path d=\"M194 135H300M465 135H573\" stroke=\"#c2ccbd\" stroke-width=\"1.5\" stroke-dasharray=\"4 6\"/><g class=\"stage-form\" id=\"chaos-stage-0\"><circle cx=\"125\" cy=\"132\" r=\"96\" fill=\"url(#chaos-potential-mist)\"/><circle cx=\"125\" cy=\"132\" r=\"65\" fill=\"none\" stroke=\"#7d9279\" stroke-dasharray=\"2 7\"/><text class=\"svg-major\" x=\"125\" y=\"246\" text-anchor=\"middle\">未取得形式</text></g><g class=\"stage-form\" id=\"chaos-stage-1\"><circle cx=\"390\" cy=\"132\" r=\"87\" fill=\"url(#chaos-potential-mist)\"/><path d=\"M331 156Q315 85 382 73T450 143 380 185 350 115 420 102\" fill=\"none\" stroke=\"#6e886c\" stroke-width=\"2\"/><text class=\"svg-major\" x=\"390\" y=\"246\" text-anchor=\"middle\">潜能进入活动</text></g><g class=\"stage-form\" id=\"chaos-stage-2\"><path d=\"M598 173L621 126 638 144 664 86 704 173Z\" fill=\"#5f7865\" opacity=\".8\"/><path d=\"M606 190Q641 169 665 186T723 182\" stroke=\"#7d9993\" stroke-width=\"4\" fill=\"none\"/><path d=\"M666 63Q658 42 676 33Q695 47 666 63Z\" fill=\"#9eac83\"/><text class=\"svg-major\" x=\"660\" y=\"246\" text-anchor=\"middle\">具体形式出现</text></g></svg>\n<div class=\"mobile-viz mobile-stages\" aria-label=\"潜能与形式的三个位置\"><div data-mobile-stage=\"0\"><span class=\"stage-glyph\" aria-hidden=\"true\">◌</span><strong>未取得形式</strong></div><span class=\"mobile-arrow\" aria-hidden=\"true\">↓</span><div data-mobile-stage=\"1\"><span class=\"stage-glyph\" aria-hidden=\"true\">≈</span><strong>潜能进入活动</strong></div><span class=\"mobile-arrow\" aria-hidden=\"true\">↓</span><div data-mobile-stage=\"2\"><span class=\"stage-glyph\" aria-hidden=\"true\">山</span><strong>具体形式出现</strong></div></div>\n<div class=\"choices\" aria-label=\"选择潜能示意阶段\"><button class=\"choice\" type=\"button\" data-stage=\"0\" aria-pressed=\"true\">未取得形式</button><button class=\"choice\" type=\"button\" data-stage=\"1\" aria-pressed=\"false\">进入活动</button><button class=\"choice\" type=\"button\" data-stage=\"2\" aria-pressed=\"false\">具体形式</button></div>\n<div class=\"readout\" id=\"chaos-stage-note\" aria-live=\"polite\"><strong>未取得形式：</strong>这里强调具体区别尚未展开，同时保留能够生成的可能。</div><figcaption class=\"caption\">三个位置帮助理解状态与生成的关系；图中出现的山水，只是“具体形式”的示意。</figcaption></figure>\n<p>因此，理解潜能，也要理解条件与活动。承认某种结果有可能出现，并不能省略它如何出现的问题。种子的生长有相应条件，泥的成形有相应活动，物理激发有相应规律。具体的可能怎样实现，需要继续讨论差异、关系与生成的过程。</p>\n<p>“本自具足”由此与创造保持一致：源头具有生成的能力，具体的表达仍可展开。完整的存在可以拥有尚未穷尽的表达方式。混沌使我们能够同时把握这两点——能力已经在，万物尚未成形；整体已经在，部分尚未分化。</p>\n<details class=\"action-fold dao-fold\"><summary>空性与潜能，可以怎样相互说明？</summary><div class=\"inside action-prose\"><p>佛教的空性从无自性说明事物依待条件而成立，也适用于已经成形的万物。麦克·罗奇借“潜能”解释空性，提醒人们：事物的呈现与条件有关。我们可以借此思考具体形式怎样保持变化的可能，同时保留本章的区分：混沌描述未分化的原初整体，空性讨论事物的存在方式。</p><figure class=\"figure art-figure\" aria-labelledby=\"chaos-flower-title\"><div class=\"eyebrow\">同一朵花 · 形态与依待</div><h3 id=\"chaos-flower-title\">花已成形，仍然依待条件</h3><div class=\"flower-canvas\"><img src=\"/assets/chaos/花与条件.jpg\" width=\"1672\" height=\"941\" loading=\"lazy\" alt=\"白花与绿色枝叶立于土壤中，根系、阳光、水分与种子各有位置\"><svg class=\"art-overlay\" viewBox=\"0 0 1672 941\" aria-hidden=\"true\"><g id=\"chaos-flower-guides\" opacity=\"0\"><path d=\"M233 148Q436 187 646 316M1371 236Q1074 269 819 398M1452 778Q1104 843 737 726M705 786L705 470\" fill=\"none\" stroke=\"#876c41\" stroke-width=\"2\" stroke-dasharray=\"6 8\"/></g><ellipse id=\"chaos-flower-focus\" cx=\"226\" cy=\"147\" rx=\"140\" ry=\"123\" fill=\"#c6aa7c\" fill-opacity=\".08\" stroke=\"#876c41\" stroke-width=\"3\" stroke-dasharray=\"6 8\" opacity=\"0\"/></svg></div><div class=\"choices\" aria-label=\"选择花的观察方式\"><button class=\"choice\" type=\"button\" data-flower=\"form\" aria-pressed=\"true\">看见形态</button><button class=\"choice\" type=\"button\" data-flower=\"conditions\" aria-pressed=\"false\">看见依待</button><button class=\"choice\" type=\"button\" data-flower=\"empty\" aria-pressed=\"false\">理解无自性</button></div><div id=\"chaos-flower-condition-picker\" hidden><p class=\"picker-label\">选择一个条件，观察它怎样参与：</p><div class=\"choices condition-picker\" aria-label=\"选择花所依待的条件\"><button class=\"choice\" type=\"button\" data-condition=\"light\" aria-pressed=\"false\">阳光</button><button class=\"choice\" type=\"button\" data-condition=\"water\" aria-pressed=\"false\">水分</button><button class=\"choice\" type=\"button\" data-condition=\"soil\" aria-pressed=\"false\">土壤与根系</button><button class=\"choice\" type=\"button\" data-condition=\"seed\" aria-pressed=\"false\">种子与过程</button><button class=\"choice\" type=\"button\" data-condition=\"name\" aria-pressed=\"false\">辨认与命名</button></div></div><p id=\"chaos-flower-note\" class=\"readout\" aria-live=\"polite\"><strong>看见形态：</strong>一朵花已经成形，具有可以辨认的样子。</p><figcaption class=\"caption\">生长条件与辨认方式各有作用。图中植物始终保留：空性说明它怎样存在。</figcaption></figure><p>一朵花已经成形，却仍依赖阳光、水分、种子与土壤。这里的启发是把潜能和条件一起理解，而不是把空性想作一种制造万物的隐形物质。</p></div></details>\n<p class=\"closing-line\">道是创造的根源。<br>一，是万物得以生成的潜能。</p>\n<div class=\"bridge\"><div class=\"kicker\">由一，走向二</div><p>混沌让创造成为可能。接下来的问题是：</p><p class=\"question\">这份尚未分化的潜能，<br>为什么要展开为差异与相对关系？</p><p>1.3「二：极性」将回答什么是极性，以及源头为什么创造极性。从“我”与“非我”的参照开始，我们进一步理解：源头怎样进入对自身的体验。</p></div>\n</section>\n</article></div></div>";
export function chaosPage(){return markup;}
export function initChaosReading(root){

const scope=root.matches?.('.chaos-reading')?root:root.querySelector('.chaos-reading');
if(!scope)return ()=>{};
const controller=new AbortController(),signal=controller.signal,doc=scope.ownerDocument;
const $=selector=>scope.querySelector(selector),$$=selector=>[...scope.querySelectorAll(selector)];
const on=(element,type,handler)=>element.addEventListener(type,handler,{signal});
function select(attr,value){$$('['+attr+']').forEach(b=>b.setAttribute('aria-pressed',String(b.getAttribute(attr)===String(value))))}
function note(target,head,body){const n=$(target);n.replaceChildren(Object.assign(doc.createElement('strong'),{textContent:head+'：'}),doc.createTextNode(body))}
const stages=[['未取得形式','这里强调具体区别尚未展开，同时保留能够生成的可能。'],['潜能进入活动','借 Hyle 的描述，追问未成形的可能如何参与生成、接受形式。'],['具体形式出现','事物已获得可以辨认的形式。潜能与已经成形的事物，处于不同的解释位置。']];
function stage(i){select('data-stage',i);$$('.stage-form').forEach((g,j)=>g.style.opacity=j<=i?'1':'.16');$$('[data-mobile-stage]').forEach((g,j)=>g.classList.toggle('reached',j<=i));note('#chaos-stage-note',...stages[i])}
$$('[data-stage]').forEach(b=>on(b,'click',()=>stage(Number(b.dataset.stage))));stage(0);
const clayForms={all:['多种可能','泥团尚未成为碗、瓶或鸟，却可以在相应的塑形活动中，取得其中一种形式。'],bowl:['成碗','泥在塑形中取得能盛物的形状。材料的可能，在这一次活动中成为一种具体形式。',333,275,276,203],vase:['成瓶','同样的泥可以在另一种塑形中，取得瓶的形式。尚未成形时，不能只把它理解成一个预先完成的碗。',982,207,187,207],bird:['成鸟','泥还可以被塑造成鸟。具体形式依赖塑形的方式；一份能力可以容纳多种成形可能。',1454,348,203,163]};
$$('[data-clay]').forEach(b=>on(b,'click',()=>{const v=b.dataset.clay,d=clayForms[v];select('data-clay',v);$('#chaos-clay-veil').setAttribute('opacity',v==='all'?'0':'.84');$('#chaos-clay-ring').setAttribute('opacity',v==='all'?'0':'1');if(v!=='all')for(const id of ['#chaos-clay-hole','#chaos-clay-ring'])['cx','cy','rx','ry'].forEach((attr,i)=>$(id).setAttribute(attr,d[i+2]));note('#chaos-clay-note',d[0],d[1])}));
const flowers={form:['看见形态','一朵花已经成形，具有可以辨认的样子。'],conditions:['看见依待','阳光、水分、种子、土壤等参与它的生长。选择下方条件，可以逐项查看。'],empty:['理解无自性','花仍然在。它依待条件而有，无法从自身独立成立。已经成形的事物，同样可以被理解为无自性。']};
$$('[data-flower]').forEach(b=>on(b,'click',()=>{const v=b.dataset.flower;select('data-flower',v);$('#chaos-flower-guides').setAttribute('opacity',v==='form'?'0':'.8');$('#chaos-flower-focus').setAttribute('opacity','0');$('#chaos-flower-condition-picker').hidden=v==='form';$$('[data-condition]').forEach(b=>b.setAttribute('aria-pressed','false'));note('#chaos-flower-note',...flowers[v])}));
const conditions={light:['阳光','光照参与植物的生长。具体需要怎样的光照，由植物种类与生长阶段等条件共同决定。',226,147,140,123],water:['水分','水分参与植物的生理活动。土壤、根系与水分之间，也形成依存关系。',1371,260,110,190],soil:['土壤与根系','根系从适宜的环境中获取水分与养分。土壤、根系和其他条件一起，使这朵花能够生长。',709,730,305,171],seed:['种子与过程','眼前的花经历了萌发与生长。它的形态包含此前的过程，不能脱离来路独立成立。',1452,778,109,102],name:['辨认与命名','我们依据花瓣、枝叶、整体形态等，将它辨认为“花”。这种依待说明识别方式，与阳光水分的生长作用分别理解。',715,354,304,268]};
$$('[data-condition]').forEach(b=>on(b,'click',()=>{const v=b.dataset.condition,d=conditions[v];select('data-condition',v);['cx','cy','rx','ry'].forEach((attr,i)=>$('#chaos-flower-focus').setAttribute(attr,d[i+2]));$('#chaos-flower-focus').setAttribute('opacity','1');note('#chaos-flower-note',d[0],d[1])}));
$$('[data-dirac]').forEach(b=>on(b,'click',()=>{const v=b.dataset.dirac;select('data-dirac',v);$('#chaos-dirac-hole').textContent=v==='filled'?'●':'○';$('#chaos-dirac-hole').classList.toggle('is-hole',v==='hole');$('#chaos-dirac-note').textContent=v==='filled'?'在历史海图景中，负能态被设想为电子填满。':'少了一个电子，留下的空穴对应正电子。这是历史图景中的解释方式。'}));
$$('[data-sea]').forEach(b=>on(b,'click',()=>{const v=b.dataset.sea;select('data-sea',v);$('#chaos-sea-detail').style.opacity=v==='wave'?'.08':'1';$('#chaos-sea-depth-label').style.opacity=v==='wave'?'.12':'1';$('#chaos-sea-note').textContent=v==='wave'?'只看这一道浪，我们能辨认它的轮廓。':'这一道浪显出形状，海仍有超出这一形状的深广。'}));
const fieldStates={
ground:{head:'基态',body:'没有电子或正电子激发，允许怎样的激发仍由场的理论结构规定。',status:'基态：无电子与正电子激发',image:'基态：层叠细线表示始终存在的理论结构，没有电子或正电子激发',chaos:'具体区别尚未展开，形成万物的能力仍在。',hyle:'尚未成形而能够受形，潜能可以进入生成。',abyss:'显现尚未展开，深广的可能并未被用尽。'},
electron:{head:'电子激发态',body:'一个电子激发被具体标出，背景结构仍在。这是在比较不同状态，并未演示真空无条件地产生电荷。',status:'电子激发态：一个电子激发',image:'电子激发态：一个电子标记显现，整体结构纹理继续保留',chaos:'一种具体区别显出，整体的可能没有被这一呈现穷尽。',hyle:'从未成形到受形：借具体激发，思考潜能取得形式的关系。',abyss:'一道“浪形”显现，深广的背景仍超出这一具体呈现。'},
pair:{head:'电子与正电子激发态',body:'同一自由电子场容纳电子与正电子激发。具体产生过程仍须满足能量、电荷等物理条件。',status:'电子与正电子激发态：两种激发共同呈现',image:'电子与正电子激发态：电子和正电子标记同时显现，整体结构纹理继续保留',chaos:'不同的具体呈现出现，仍须放回整体理解。',hyle:'潜能可以取得不同形式，并不等于预先存放了全部成品。',abyss:'不同的“浪形”显现，仍未用尽背景的深广。'}
};
function renderFieldState(value){const state=fieldStates[value];if(!state)return;select('data-vacuum',value);$('#chaos-field-scene').dataset.fieldState=value;$('#chaos-field-scene').setAttribute('aria-label',state.image);$('#chaos-electron').classList.toggle('visible',value!=='ground');$('#chaos-positron').classList.toggle('visible',value==='pair');note('#chaos-vacuum-note',state.head,state.body);$('#chaos-vacuum-status').textContent=state.status;$('#chaos-field-chaos').textContent=state.chaos;$('#chaos-field-hyle').textContent=state.hyle;$('#chaos-field-abyss').textContent=state.abyss;}
$$('[data-vacuum]').forEach(button=>on(button,'click',()=>renderFieldState(button.dataset.vacuum)));
renderFieldState('ground');

const lenses={formless:['无形','尚无可逐一辨认的具体万物；生成的可能仍然在。'],whole:['整体','部分尚未分化；万物的出现，发生在同一整体之中。'],potential:['潜能','具体形式尚未实现；使形式得以生成的能力已经在。']};
$$('[data-lens]').forEach(b=>on(b,'click',()=>{const v=b.dataset.lens;select('data-lens',v);$$('[data-lens-art]').forEach(g=>g.setAttribute('opacity',g.dataset.lensArt===v?'1':'.12'));note('#chaos-lens-note',...lenses[v]);}));
const creation={source:['创造的根源','道具有觉知与创造性。上一章提出它认识自身的根本欲望。'],potential:['本章的中心','源头展开自身的潜能，使不同形式的生成成为可能。'],form:['具体的实现','一种可能取得确定形式。差异、关系与生成的过程，将在后续章节展开。']};
$$('[data-creation]').forEach(b=>on(b,'click',()=>{select('data-creation',b.dataset.creation);note('#chaos-creation-note',...creation[b.dataset.creation]);}));

return ()=>controller.abort();
}
